import{_ as s,l as o,o as e,c as r,v as t,p as i,x as d,d as l,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"ECDSA / EdDSA","description":"","frontmatter":{"title":"ECDSA / EdDSA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ecdsa-eddsa.md","filePath":"cs/ecdsa-eddsa.md","lastUpdated":1789023840000}'),h={name:"cs/ecdsa-eddsa.md"};function A(p,a,S,D,C,_){const n=o("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="ecdsa-eddsa" tabindex="-1">ECDSA / EdDSA <a class="header-anchor" href="#ecdsa-eddsa" aria-label="Permalink to &quot;ECDSA / EdDSA&quot;">​</a></h1><div class="epigraph"><p>曲线上的签名：ECDSA 沿用 DSA 的随机 $k$ 合同，$k$ 泄漏或复用即私钥泄漏；Ed25519 把 $k$ 从私钥与消息确定性派生，去掉这口坑。</p><footer>—— Johnson, Menezes and Vanstone 对 ECDSA；Bernstein, Duif, Lange, Schwabe and Yang, Ed25519；RFC 8032</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/ecdh-x25519">ECDH 与 X25519</a>用曲线做协商。缺口是<strong>认证</strong>：签名。主干<a href="/cs/mac-signature">MAC 与签名</a>已分对称与非对称；本课落到曲线族与确定性。不重写证书链。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ECDSA 验证用公钥点；签名生成需要每次唯一且保密的 nonce \\(k\\)。Sony 一类事故是 \\(k\\) 复用——本课只陈述「复用则线性方程出私钥」，不给求解步骤。EdDSA（Ed25519）：\\(k\\) 由哈希确定，去掉 RNG 失败。缺口是签名合同与密钥分离（签钥 ≠ DH 钥）。</p><h3 id="规范编码" tabindex="-1">规范编码 <a class="header-anchor" href="#规范编码" aria-label="Permalink to &quot;规范编码&quot;">​</a></h3><p>点压缩与规范签名可防可塑。协议应验规范形式，避免同一逻辑消息多种编码。</p><p><span class="marginnote">RFC 8032。FIPS 186 含 ECDSA。阈值与硬件签名更后。本课不提供从两枚签名提取私钥的程序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：ECDSA 要好 RNG；Ed25519 确定性。消息先哈希。域分离：不同协议用不同上下文。指出 JWT 等后课若允许 <code>alg=none</code> 是协议误用，不是曲线的锅。</p>',12)),(e(),i(c,null,{default:d(()=>[E(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SK%5B%22%E7%AD%BE%E9%92%A5%22%5D%20--%3E%20SIG%5B%22%E7%AD%BE%E5%90%8D%22%5D%0A%20%20MSG%5B%22%E6%B6%88%E6%81%AF%E5%93%88%E5%B8%8C%22%5D%20--%3E%20SIG%0A%20%20K%5B%22ECDSA%3A%20%E9%9A%8F%E6%9C%BA%20k%20%2F%20EdDSA%3A%20%E6%B4%BE%E7%94%9F%20k%22%5D%20--%3E%20SIG%0A%20%20SIG%20--%3E%20VRF%5B%22%E5%85%AC%E9%92%A5%E5%8F%AF%E9%AA%8C%22%5D%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>签名服务不可否认与握手认证（证书里的公钥）。ECDH 服务保密密钥。两者都在曲线上，威胁模型不同：签钥泄漏是伪造，DH 长期钥泄漏在无前向保密时是解密历史。CSPRNG 下一课专收「\\(k\\) 从哪来」。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把双线性对和 BLS 插进主干。随机数生成器下一课：不仅服务 ECDSA，也服务 OAEP 种子与 nonce。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ECDH 协商；ECDSA/EdDSA 认证。</li><li>ECDSA 的 \\(k\\) 复用是规格级失败；Ed25519 确定性派生。</li><li>签钥与 DH 钥分离。</li><li>下一课 CSPRNG：种子与熵。</li><li>出处：RFC 8032；Johnson, Menezes and Vanstone；Bernstein et al., Ed25519。</li></ul>',8))])}const f=s(h,[["render",A]]);export{m as __pageData,f as default};
